import copyimport jsonimport osimport refrom urllib.parse import urlparsefrom playwright.sync_api import Page, Route, expectEMAIL = os.environ.get("EVENTHUB_EMAIL", "swarooparajbhan@gmail.com")PASSWORD = os.environ.get("EVENTHUB_PASSWORD", "your-password-here")# Step 3: deterministic replacement valuesPATCH = {"ref": "PATCH-7777", "title": "Patched Mock Summit", "tickets": 3, "total": 4500}PATCH_TOTAL_TEXT = f"${PATCH['total']:,}"          # "$4,500"# ---------- helpers that find fields in any JSON shape ----------def norm(key: str) -> str:    return key.lower().replace("_", "").replace("-", "")def field_of(path: tuple):    last = norm(path[-1])    if "ref" in last and "refund" not in last:        return "ref"    if last in ("title", "eventtitle", "eventname") or (        last == "name" and any("event" in norm(p) for p in path[:-1])    ):        return "title"    if last in ("quantity", "tickets", "ticketcount", "numberoftickets", "ticketsbooked", "numtickets"):        return "tickets"    if last in ("totalprice", "totalamount", "total", "totalpaid", "amount"):        return "total"    return Nonedef walk(obj, path=()):    if isinstance(obj, dict):        for k, v in list(obj.items()):            yield obj, k, path + (k,)            yield from walk(v, path + (k,))    elif isinstance(obj, list):        for v in obj:            yield from walk(v, path)def patch_item(item, values) -> set:    found = set()    for container, key, path in walk(item):        f = field_of(path)        old = container[key]        if f and not isinstance(old, (dict, list)):            if isinstance(old, str):                container[key] = f"${values[f]:,}" if f == "total" and old.strip().startswith("$") else str(values[f])            else:                container[key] = values[f]            found.add(f)    return founddef read_field(item, logical):    for container, key, path in walk(item):        if field_of(path) == logical and not isinstance(container[key], (dict, list)):            return container[key]    return Nonedef read_id(item):    return next(item[k] for k in item if norm(k) in ("id", "bookingid"))def find_email(body):    for container, key, path in walk(body):        v = container[key]        if "email" in norm(key) and isinstance(v, str) and "@" in v:            return v    return Nonedef find_list(body):    if isinstance(body, list):        return body    if isinstance(body, dict):        for v in body.values():            found = find_list(v)            if found is not None:                return found    return Nonedef fulfill_json(route: Route, response, body):    headers = {k: v for k, v in response.headers.items()               if k.lower() not in ("content-length", "content-encoding", "transfer-encoding")}    route.fulfill(status=response.status, headers=headers, json=body)# ---------- route interception (steps 2, 3, 4, 9) ----------def install_patch(page: Page, state: dict):    def handler(route: Route):        req = route.request        if req.method != "GET":            return route.continue_()        path = urlparse(req.url).path.rstrip("/")        detail = re.search(r"/api/bookings/([^/]+)$", path)        if detail:            if "id" in state and detail.group(1) == str(state["id"]):                resp = route.fetch()                body = resp.json()                state.setdefault("email", find_email(body))       # real, unpatched value                found = patch_item(body, PATCH)                assert {"ref", "title", "tickets", "total"} <= found, (                    f"Detail fields not found {found}: {json.dumps(body)[:800]}")                return fulfill_json(route, resp, body)            return route.continue_()        if path.endswith("/api/bookings"):            resp = route.fetch()            body = resp.json()            items = find_list(body)            assert items and len(items) >= 2, "Need at least 2 bookings in My Bookings first"            if "id" not in state:                                 # choose the one record to patch                target = items[0]                state["id"] = read_id(target)                state["original"] = copy.deepcopy(target)                state["orig_ref"] = read_field(target, "ref")                state["other_ref"] = read_field(items[1], "ref")                state["count"] = len(items)            target = next(i for i in items if str(read_id(i)) == str(state["id"]))            found = patch_item(target, PATCH)                     # id is never touched            assert {"ref", "title", "tickets", "total"} <= found, (                f"List fields not found {found}: {json.dumps(target)[:800]}")            state["patched"] = copy.deepcopy(target)              # step 5: stored patched object            return fulfill_json(route, resp, body)        route.continue_()    page.route("**/api/bookings**", handler)# ---------- UI helpers ----------def login(page: Page):    page.goto("/login")    page.get_by_label("Email").fill(EMAIL)    page.get_by_label("Password").fill(PASSWORD)    page.get_by_role("button", name=re.compile("sign in", re.I)).click()    expect(page.get_by_role("button", name="Logout")).to_be_visible()def find_card(page: Page, ref: str):    """Locate a booking card by its reference text only, never by position."""    badge = page.get_by_text(ref, exact=True)    expect(badge).to_have_count(1, timeout=30_000)    return badge.locator("xpath=ancestor::*[.//*[normalize-space()='View Details']][1]")def payment_summary(page: Page):    return page.locator("main").locator("xpath=//h2[normalize-space()='Payment Summary']/parent::*")    expect.set_options(timeout=30_000)def test_patch_one_booking(page: Page):    state = {}    # Step 1    login(page)    my_bookings_link = page.get_by_role("navigation").first.get_by_role("link", name="My Bookings")    expect(my_bookings_link).to_be_visible()    # Steps 2-4: interception installed BEFORE opening My Bookings    install_patch(page, state)    # Step 5    with page.expect_response(            lambda r: r.url.split("?")[0].rstrip("/").endswith("/api/bookings"),            timeout=30_000,    ):        my_bookings_link.click()        expect(page.get_by_role("heading", name="My Bookings")).to_be_visible()    # Step 6: patched card found by reference text    card = find_card(page, PATCH["ref"])    expect(card).to_be_visible()    expect(card).to_contain_text(PATCH["title"])    expect(card).to_contain_text(re.compile(rf"\b{PATCH['tickets']}\s*tickets?\b", re.I))    expect(card).to_contain_text(PATCH_TOTAL_TEXT)    patched = state["patched"]                                    # stored patched object    assert read_field(patched, "ref") == PATCH["ref"]    assert state["count"] >= 2    # Step 7: another live card is untouched and different    expect(page.get_by_text(state["orig_ref"], exact=True)).to_have_count(0)   # old ref is gone    other = find_card(page, state["other_ref"])    expect(other).to_be_visible()    expect(other).not_to_contain_text(PATCH["title"])    assert state["other_ref"] != PATCH["ref"]    # Step 8: View Details uses the preserved booking id    card.get_by_text("View Details").click()    expect(page).to_have_url(re.compile(rf"/bookings/{re.escape(str(state['id']))}$"))    # Steps 9-10: detail values match the patched list; email stays real    main = page.locator("main")    expect(main.get_by_role("navigation")).to_contain_text(PATCH["ref"])        # breadcrumb    expect(page.get_by_role("heading", level=1)).to_contain_text(PATCH["title"])    summary = payment_summary(page)    expect(summary).to_contain_text(re.compile(rf"Tickets\s*{PATCH['tickets']}(?!\d)"))    expect(summary).to_contain_text(re.compile(rf"Total Paid\s*{re.escape(PATCH_TOTAL_TEXT)}"))    assert state.get("email"), "Original customer email was not captured"    expect(main).to_contain_text(state["email"])    detail_total = re.search(r"Total Paid\s*(\$[\d,]+(?:\.\d+)?)", summary.inner_text()).group(1)    # Step 11: back to My Bookings, re-find by reference    page.get_by_role("link", name=re.compile("Back to My Bookings")).click()    expect(page.get_by_role("heading", name="My Bookings")).to_be_visible()    card = find_card(page, PATCH["ref"])    expect(card).to_contain_text(detail_total)    page.unroute_all(behavior="ignoreErrors")